<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { useProductStore } from '@/stores/product';
import ProductCard from '@/components/common/ProductCard.vue';
import { applyMenuFilterDraft, createMenuFilterDraft, menuFilterCount, paginationRange } from '@/utils/menuFilters';

const store = useProductStore();
const route = useRoute();
const router = useRouter();
const q = ref('');
const category = ref(null);
const price = ref('ALL');
const min = ref('');
const max = ref('');
const availability = ref('ALL');
const discounted = ref(false);
const bestSeller = ref(false);
const sort = ref('name');
const page = ref(1);
const view = ref('grid');
const drawer = ref(false);
const filtersOpen = ref(false);
const draft = ref(createMenuFilterDraft());
const drawerPanel = ref(null);
const closeButton = ref(null);
const drawerTrigger = ref(null);
const pageSize = 12;
let searchTimer;
let restoring = false;

const prices = [{ key: 'ALL', label: 'Mọi mức giá' }, { key: 'UNDER_30', label: 'Dưới 30.000₫' }, { key: '30_60', label: '30.000₫ – 60.000₫' }, { key: 'OVER_60', label: 'Trên 60.000₫' }, { key: 'CUSTOM', label: 'Tùy chỉnh' }];
const availabilityOptions = [{ key: 'ALL', label: 'Tất cả' }, { key: 'AVAILABLE', label: 'Còn hàng' }, { key: 'OUT_OF_STOCK', label: 'Hết hàng' }, { key: 'OUTSIDE_HOURS', label: 'Ngoài giờ bán' }];
const sortOptions = [{ key: 'name', label: 'Tên A–Z' }, { key: 'best-selling', label: 'Bán chạy' }, { key: 'newest', label: 'Mới nhất' }, { key: 'price-asc', label: 'Giá thấp → cao' }, { key: 'price-desc', label: 'Giá cao → thấp' }, { key: 'discount-desc', label: 'Giảm nhiều nhất' }];
const currentFilters = computed(() => ({ price: price.value, min: min.value, max: max.value, availability: availability.value, discounted: discounted.value, bestSeller: bestSeller.value }));
const filterCount = computed(() => menuFilterCount(currentFilters.value));
const categories = computed(() => [{ id: null, name: 'Tất cả', count: store.allCategories.reduce((sum, item) => sum + item.productCount, 0) || store.allProducts.length }, ...store.allCategories.map(item => ({ ...item, count: item.productCount || store.allProducts.filter(product => product.categoryId === item.id).length }))]);
const totalPages = computed(() => store.catalogMeta.totalPages);
const pages = computed(() => [...new Set([1, totalPages.value, page.value - 1, page.value, page.value + 1].filter(value => value > 0 && value <= totalPages.value).sort((a, b) => a - b))].reduce((result, value, index, values) => { if (index && value - values[index - 1] > 1) result.push('…'); result.push(value); return result; }, []));
const range = computed(() => paginationRange(page.value, pageSize, store.catalogMeta.totalItems));
const chips = computed(() => [q.value && { key: 'q', label: `“${q.value}”` }, category.value && { key: 'category', label: store.allCategories.find(item => item.id === category.value)?.name }, price.value !== 'ALL' && { key: 'price', label: prices.find(item => item.key === price.value)?.label }, availability.value !== 'ALL' && { key: 'availability', label: availabilityOptions.find(item => item.key === availability.value)?.label }, discounted.value && { key: 'discounted', label: 'Đang giảm giá' }, bestSeller.value && { key: 'bestSeller', label: 'Bán chạy' }].filter(Boolean));

function priceParams() {
  if (price.value === 'UNDER_30') return { maxPrice: 29999 };
  if (price.value === '30_60') return { minPrice: 30000, maxPrice: 60000 };
  if (price.value === 'OVER_60') return { minPrice: 60001 };
  if (price.value === 'CUSTOM') return { minPrice: min.value || undefined, maxPrice: max.value || undefined };
  return {};
}
function fetchCatalog() { store.fetchCatalog({ q: q.value.trim() || undefined, categoryId: category.value || undefined, ...priceParams(), availability: availability.value, discounted: discounted.value || undefined, sold: bestSeller.value ? 1 : undefined, sort: sort.value, page: page.value - 1, size: pageSize }); }
function hydrate() {
  restoring = true;
  q.value = String(route.query.q || ''); category.value = route.query.category ? Number(route.query.category) : null;
  price.value = prices.some(item => item.key === route.query.price) ? route.query.price : 'ALL'; min.value = String(route.query.min || ''); max.value = String(route.query.max || '');
  availability.value = availabilityOptions.some(item => item.key === route.query.availability) ? route.query.availability : 'ALL'; discounted.value = route.query.discounted === 'true'; bestSeller.value = route.query.bestSeller === 'true';
  sort.value = sortOptions.some(item => item.key === route.query.sort) ? route.query.sort : 'name'; page.value = Math.max(1, Number(route.query.page) || 1); view.value = route.query.view === 'list' ? 'list' : 'grid';
  nextTick(() => { restoring = false; fetchCatalog(); });
}
function queryValue() { const query = {}; if (q.value.trim()) query.q = q.value.trim(); if (category.value) query.category = category.value; if (price.value !== 'ALL') query.price = price.value; if (price.value === 'CUSTOM' && min.value) query.min = min.value; if (price.value === 'CUSTOM' && max.value) query.max = max.value; if (availability.value !== 'ALL') query.availability = availability.value; if (discounted.value) query.discounted = 'true'; if (bestSeller.value) query.bestSeller = 'true'; if (sort.value !== 'name') query.sort = sort.value; if (page.value > 1) query.page = page.value; if (view.value === 'list') query.view = 'list'; return query; }
function navigate(replace = false) { if (!restoring) router[replace ? 'replace' : 'push']({ query: queryValue() }); }
function resetRefinements() { price.value = 'ALL'; min.value = ''; max.value = ''; availability.value = 'ALL'; discounted.value = false; bestSeller.value = false; page.value = 1; }
function reset() { q.value = ''; category.value = null; resetRefinements(); sort.value = 'name'; }
function remove(key) { if (key === 'q') q.value = ''; if (key === 'category') category.value = null; if (key === 'price') { price.value = 'ALL'; min.value = ''; max.value = ''; } if (key === 'availability') availability.value = 'ALL'; if (key === 'discounted') discounted.value = false; if (key === 'bestSeller') bestSeller.value = false; }
function openDrawer() { draft.value = createMenuFilterDraft(currentFilters.value); drawer.value = true; document.body.style.overflow = 'hidden'; nextTick(() => closeButton.value?.focus()); }
function closeDrawer() { drawer.value = false; document.body.style.overflow = ''; nextTick(() => drawerTrigger.value?.focus()); }
function applyDrawer() { const value = applyMenuFilterDraft(draft.value); price.value = value.price; min.value = value.min; max.value = value.max; availability.value = value.availability; discounted.value = value.discounted; bestSeller.value = value.bestSeller; closeDrawer(); }
function clearDraft() { draft.value = createMenuFilterDraft(); }
function onKeydown(event) {
  if (!drawer.value) return;
  if (event.key === 'Escape') return closeDrawer();
  if (event.key !== 'Tab') return;
  const focusable = [...drawerPanel.value.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled])')];
  if (!focusable.length) return;
  const first = focusable[0]; const last = focusable[focusable.length - 1];
  if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
}
watch(() => route.query, hydrate);
watch([category, price, min, max, availability, discounted, bestSeller, sort], () => { if (restoring) return; page.value = 1; navigate(); });
watch(page, () => { if (!restoring) navigate(); });
watch(view, () => { if (!restoring) navigate(); });
watch(q, () => { if (restoring) return; page.value = 1; clearTimeout(searchTimer); searchTimer = setTimeout(() => navigate(true), 300); });
onMounted(() => { hydrate(); store.init(); window.addEventListener('keydown', onKeydown); });
onBeforeUnmount(() => { clearTimeout(searchTimer); document.body.style.overflow = ''; window.removeEventListener('keydown', onKeydown); });
</script>

<template>
  <div class="menu-page">
    <section class="menu-hero"><div class="container hero-inner"><nav class="breadcrumb" aria-label="Điều hướng"><router-link to="/home">Trang chủ</router-link><i class="bi bi-chevron-right" aria-hidden="true"></i><span>Thực đơn</span></nav><div class="hero-grid"><div class="hero-copy"><p>FASTGUY MENU</p><h1>Món ngon,<br><em>chọn theo cách bạn.</em></h1><span>Khám phá thực đơn đa dạng, lọc đúng khẩu vị và đặt món chỉ trong vài thao tác.</span></div><div class="hero-search"><label class="search"><span class="sr-only">Tìm món</span><i class="bi bi-search" aria-hidden="true"></i><input v-model="q" type="search" placeholder="Bạn muốn ăn gì hôm nay?"></label><div class="quick-info"><span>Đặt món nhanh</span><span>Giá rõ ràng</span></div></div></div></div></section>
    <div class="container menu-body">
      <div class="compact-toolbar"><div class="category-chips" aria-label="Lọc theo danh mục"><button v-for="item in categories" :key="item.id ?? 'all'" :class="{ active: category === item.id }" @click="category = item.id">{{ item.name }}<small>{{ item.count }}</small></button></div><button class="desktop-filter-toggle" aria-controls="menu-filters" :aria-expanded="filtersOpen" @click="filtersOpen = !filtersOpen"><i class="fa-solid fa-sliders" aria-hidden="true"></i> Bộ lọc <span v-if="filterCount">{{ filterCount }}</span></button></div>
      <div class="mobile-tools"><button ref="drawerTrigger" aria-controls="mobile-menu-filters" :aria-expanded="drawer" @click="openDrawer"><i class="fa-solid fa-sliders" aria-hidden="true"></i> Bộ lọc <span v-if="filterCount">{{ filterCount }}</span></button><label><span class="sr-only">Sắp xếp</span><select v-model="sort" aria-label="Sắp xếp"><option v-for="item in sortOptions" :key="item.key" :value="item.key">{{ item.label }}</option></select></label></div>
      <aside id="menu-filters" class="menu-sidebar advanced-filters filter-dropdown" :class="{ open: filtersOpen }"><div class="filter-head"><h2>Lọc món</h2><button v-if="filterCount" @click="resetRefinements">Xóa bộ lọc</button></div><fieldset class="filter-group"><legend>Ưu tiên</legend><label><input v-model="discounted" type="checkbox"> Đang giảm giá</label><label><input v-model="bestSeller" type="checkbox"> Bán chạy</label></fieldset><fieldset class="filter-group"><legend>Khoảng giá</legend><label v-for="item in prices" :key="item.key"><input v-model="price" type="radio" name="price" :value="item.key"> {{ item.label }}</label><div v-if="price === 'CUSTOM'" class="price-range"><input v-model="min" type="number" min="0" placeholder="Từ" aria-label="Giá tối thiểu"><input v-model="max" type="number" min="0" placeholder="Đến" aria-label="Giá tối đa"></div></fieldset><fieldset class="filter-group"><legend>Tình trạng</legend><label v-for="item in availabilityOptions" :key="item.key"><input v-model="availability" type="radio" name="availability" :value="item.key"> {{ item.label }}</label></fieldset></aside>
      <div v-if="drawer" class="backdrop" @click="closeDrawer"></div>
      <aside v-if="drawer" id="mobile-menu-filters" ref="drawerPanel" class="mobile-filter-sheet" role="dialog" aria-modal="true" aria-labelledby="mobile-filter-title"><div class="drawer-head"><h2 id="mobile-filter-title">Bộ lọc</h2><button ref="closeButton" aria-label="Đóng bộ lọc" @click="closeDrawer"><i class="fa-solid fa-xmark" aria-hidden="true"></i></button></div><div class="sheet-content"><fieldset class="filter-group"><legend>Ưu tiên</legend><label><input v-model="draft.discounted" type="checkbox"> Đang giảm giá</label><label><input v-model="draft.bestSeller" type="checkbox"> Bán chạy</label></fieldset><fieldset class="filter-group"><legend>Khoảng giá</legend><label v-for="item in prices" :key="item.key"><input v-model="draft.price" type="radio" name="mobile-price" :value="item.key"> {{ item.label }}</label><div v-if="draft.price === 'CUSTOM'" class="price-range"><input v-model="draft.min" type="number" min="0" placeholder="Từ" aria-label="Giá tối thiểu"><input v-model="draft.max" type="number" min="0" placeholder="Đến" aria-label="Giá tối đa"></div></fieldset><fieldset class="filter-group"><legend>Tình trạng</legend><label v-for="item in availabilityOptions" :key="item.key"><input v-model="draft.availability" type="radio" name="mobile-availability" :value="item.key"> {{ item.label }}</label></fieldset></div><div class="sheet-footer"><button class="clear-draft" @click="clearDraft">Xóa tất cả</button><button class="apply" @click="applyDrawer">Xem {{ store.catalogMeta.totalItems }} món</button></div></aside>
      <main class="content">
        <div v-if="chips.length" class="active-filters"><strong>Đang lọc:</strong><div class="chips"><button v-for="chip in chips" :key="chip.key" @click="remove(chip.key)">{{ chip.label }} <i class="fa-solid fa-xmark" aria-hidden="true"></i></button><button class="clear" @click="reset">Xóa tất cả</button></div></div>
        <header class="result-summary"><div class="result-copy"><span>Thực đơn FastGuy</span><h2>Kết quả món ăn</h2><strong class="result-count">{{ store.catalogMeta.totalItems }} món phù hợp</strong><p class="result-context">{{ chips.length ? `Đang áp dụng ${chips.length} bộ lọc` : 'Tất cả món đang có trong thực đơn' }}</p></div><div class="result-actions"><label class="toolbar-sort">Sắp xếp: <select v-model="sort" aria-label="Sắp xếp"><option v-for="item in sortOptions" :key="item.key" :value="item.key">{{ item.label }}</option></select></label><div class="view-toggle" aria-label="Kiểu hiển thị"><button :class="{ active: view === 'grid' }" aria-label="Dạng lưới" @click="view = 'grid'"><i class="bi bi-grid" aria-hidden="true"></i></button><button :class="{ active: view === 'list' }" aria-label="Dạng danh sách" @click="view = 'list'"><i class="bi bi-list" aria-hidden="true"></i></button></div></div></header>
        <div v-if="store.catalogLoading" class="grid"><div v-for="n in 12" :key="n" class="skeleton"></div></div><section v-else-if="store.catalogError" class="state" role="alert"><h2>Không thể tải thực đơn</h2><p>{{ store.catalogError }}</p><button @click="fetchCatalog">Thử lại</button></section><section v-else-if="!store.catalog.length" class="state"><h2>Không tìm thấy món</h2><button @click="reset">Xóa bộ lọc</button></section><template v-else><div class="grid" :class="{ list: view === 'list' }"><ProductCard v-for="product in store.catalog" :key="product.productId" :product="product" :list-mode="view === 'list'" /></div><div v-if="totalPages > 1" class="pagination-row"><span class="pagination-summary">Hiển thị {{ range.from }}–{{ range.to }} trong {{ store.catalogMeta.totalItems }} món</span><nav class="pagination" aria-label="Phân trang"><button :disabled="page === 1" aria-label="Trang trước" @click="page--">‹</button><template v-for="item in pages" :key="item"><span v-if="item === '…'">…</span><button v-else :class="{ active: page === item }" :aria-current="page === item ? 'page' : undefined" @click="page = item">{{ item }}</button></template><button :disabled="page === totalPages" aria-label="Trang sau" @click="page++">›</button></nav></div></template>
      </main>
    </div>
  </div>
</template>

<style scoped>
